(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*5 + Math.cos(y*0.035+t*0.45)*4;
  const w2y = Math.cos(y*0.038+t*0.4)*5 + Math.sin(x*0.042-t*0.55)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08+Math.sin(t*0.8)*0.02, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1+Math.cos(t*0.6)*0.02, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06+Math.sin(t*0.9)*0.015, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12+Math.cos(t*0.7)*0.02, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07+Math.sin(t*0.5)*0.015, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09+Math.cos(t*0.85)*0.02, 1.9],
    [400+Math.sin(t*0.45+3)*70, 120+Math.cos(t*0.65+4)*60, 0.11+Math.sin(t*0.75)*0.018, 2.1],
    [80+Math.cos(t*0.55+2)*90, 40+Math.sin(t*0.75+1)*50, 0.065+Math.cos(t*0.95)*0.015, 2.4],
    [240+Math.sin(t*0.25+6)*160, 120+Math.cos(t*0.45+3)*100, 0.055+Math.sin(t)*0.01, 2.8]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * 0.5;
  }
  const act = aS/9, inh = iS/9, harm = hS/9;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dwx = Math.sin(sx*0.03+t*0.7)*8, dwy = Math.cos(sy*0.03-t*0.6)*8;
  const bg3 = Math.sin((sx+dwx)*0.06+(sy+dwy)*0.06+t*1.5)*0.3;
  const bg = bg1 + bg2 + bg3;
