  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2 = (Math.sin(dist*0.08+ang*2-t*2.0) + Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const spiral = sp1 + sp2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act*0.8 + harm - inh*0.5 + spiral*1.2)*1.8);
  const rdMix = rd1*0.7 + rd2*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const contour = Math.abs(Math.sin((act-inh)*Math.PI*3))*0.15;
  const blend = rdMix*0.65 + cell*0.2 + contour*0.15, v = blend*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[15,70,115],[20,120,130],[45,160,120],[140,180,80],[210,190,60],[230,140,55],[210,90,65],[170,50,70],[110,25,60],[60,15,50],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const intensity = Math.abs(rdMix), lum = 0.75 + intensity*0.25 + Math.sin(rdMix*Math.PI)*0.1;
  const edgeGlow = intensity > 0.6 ? (intensity-0.6)*1.5 : 0;
  const hl = rd2 > 0.3 ? (rd2-0.3)*0.3 : 0;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + edgeGlow*40 + hl*30)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + edgeGlow*20 + hl*50)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + edgeGlow*60 + hl*20)|0)
  ];
}
